package com.logistics.gateway;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import java.nio.charset.StandardCharsets;import java.time.Instant;import java.util.*;import javax.crypto.SecretKey;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;
@Service public class JwtTokenService {private final SecretKey key;private final String issuer,audience;public JwtTokenService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.issuer}")String issuer,@Value("${app.jwt.audience}")String audience){if(secret.length()<32)throw new IllegalArgumentException("JWT secret must be at least 256 bits");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.issuer=issuer;this.audience=audience;}public Claims parse(String token){return Jwts.parser().verifyWith(key).requireIssuer(issuer).requireAudience(audience).build().parseSignedClaims(token).getPayload();}}
